contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // Give c some Ether via the payable fallback so depositsCount increases.
        uint256 amount;
        if (address(this).balance > 0) {
            amount = address(this).balance;
        } else {
            amount = 0;
        }

        // Snapshot the before-values through public surface.
        uint256 cBalBefore = address(c).balance;
        uint256 ownerBalBefore = address(this).balance;
        uint256 depositsBefore = c.depositsCount();
        address cOwnerBefore = c.owner();

        // Send ether into c if we have any, using the fallback.
        if (amount > 0) {
            require(address(this).balance >= amount);
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent);
        }

        cBalBefore = address(c).balance;
        ownerBalBefore = address(this).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount();

        assert(
            !reverted &&
            cBalAfter == 0 &&
            depositsAfter == depositsBefore &&
            c.owner() == cOwnerBefore &&
            address(this).balance >= ownerBalBefore + cBalBefore
        );
    }

    receive() external payable {}
    fallback() external payable {}
}

