contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        require(value <= address(c).balance, "insufficient balance");
        uint beforeBal = address(c).balance;

        bool callOk = target.call("" ); // just probing? no! avoid state changes on target

        bool reverted;
        try c.sendMoney(target, value) { reverted = false; } catch { reverted = true; }

        uint afterBal = address(c).balance;

        // The low-level call from c to target uses empty calldata.
        // We determine success by checking whether balance decreased on success.
        // But we need a general rule independent of probing target again.
        // The rule: sendMoney reverts iff the target rejects the transfer.
        // On success, c pays exactly value; on failure, c pays nothing.
        assert(reverted ? afterBal == beforeBal : afterBal + value == beforeBal);
    }

    receive() external payable {}
}

